    assert.equal(kept.moved.length, 1);
    for (const name of ['id_rsa', 'server.pem', 'prod.env'])
      await writeFile(join(shared, name), 'synthetic secret');
    await mkdir(join(shared, 'Library'));
    for (const name of ['id_rsa', 'server.pem', 'prod.env', 'Library'])
      await assert.rejects(
        files.execute('LOCAL_FILES_READ', { path: join(shared, name) }),
        /secret/,
      );
    const sorted = join(shared, 'sorted');
    await files.keepOut(turn, ' ~/Downloads/sorted/ ', pool);
    assert.deepEqual(keep, [sorted]);
    const shown = (await files.execute('LOCAL_FILES_LIST', { path: shared })) as {
      entries: Array<{ name: string }>;
    };
    for (const name of ['sorted', 'id_rsa', 'server.pem', 'prod.env', 'Library'])
      assert.ok(!shown.entries.some((item) => item.name === name), name);
    const blocked = (await files.execute('LOCAL_FILES_MOVE', {
      moves: [
        { from: note, to: join(sorted, 'note.txt') },
        { from: join(sorted, 'a.txt'), to: join(shared, 'out.txt') },
      ],
    })) as { failed: Array<{ error: string }> };
    assert.equal(blocked.failed.length, 2);
    assert.match(blocked.failed[0]!.error, /keep out/);
    const beside = (await files.execute('LOCAL_FILES_MOVE', {
      moves: [{ from: note, to: join(shared, 'note-moved.txt') }],
    })) as { moved: unknown[] };
    assert.equal(beside.moved.length, 1);
    await files.execute('LOCAL_FILES_MOVE', {
      moves: [{ from: join(shared, 'note-moved.txt'), to: note }],
    });
    for (const [action, args] of [
      ['LOCAL_FILES_LIST', { path: join(sorted, '..', 'sorted') }],
      ['LOCAL_FILES_READ', { path: join(sorted, 'a.txt') }],
      ['LOCAL_FILES_CREATE_FOLDER', { path: join(sorted, 'new') }],
      ['LOCAL_FILES_EXPORT', { file, path: join(sorted, 'copy.pdf') }],
      ['LOCAL_FILES_TRASH', { paths: [shared] }],
    ] as const)
      await assert.rejects(files.prepare(action, args), /keep out/, action);
    assert.equal(
      ((await files.execute('LOCAL_FILES_READ', { path: note })) as { text: string }).text,
      '1 two two',
    );
    await files.keepOut(turn, join(shared, 'Later', 'New'), pool);
    assert.equal(keep.at(-1), join(shared, 'Later', 'New'));
    const replaced = (await files.execute('LOCAL_FILES_WRITE', {
      path: note,
      text: 'fresh',
      overwrite: true,
    })) as { previousVersion?: string };
    assert.equal(replaced.previousVersion, 'moved to the Trash');
    assert.equal(await readFile(note, 'utf8'), 'fresh');
    assert.equal(await readFile(join(trash, 'note.txt'), 'utf8'), '1 two two');
    const late = join(shared, 'late.txt');
    await writeFile(late, 'old');
    await assert.rejects(
      files.execute('LOCAL_FILES_EDIT', {
        path: late,
        edits: [{ oldText: 'old', newText: 'new' }],
      }),
      /is unchanged/,
    );
    assert.equal(await readFile(late, 'utf8'), 'old');
    assert.deepEqual(
      (await readdir(shared)).filter((name) => name.startsWith('.nod-')),
      [],
    );
    await writeFile(join(shared, 'tool.sh'), 'echo hi');
    const kinds = (await files.execute('LOCAL_FILES_MOVE', {
      moves: [{ from: join(shared, 'tool.sh'), to: join(shared, 'tool.bash') }],
    })) as { failed: Array<{ error: string }> };
    assert.match(kinds.failed[0]?.error ?? '', /program or shortcut/);
    await symlink('a-target.txt', join(shared, 'relative'));
    const relative = (await files.execute('LOCAL_FILES_MOVE', {
      moves: [
        { from: join(shared, 'relative'), to: join(shared, 'Installers', 'relative') },
        { from: join(shared, 'relative'), to: join(shared, 'renamed') },
      ],
    })) as { moved: unknown[]; failed: Array<{ error: string }> };
    assert.match(relative.failed[0]!.error, /relative link/);
    assert.equal(relative.moved.length, 1);
    const off = createLocalFiles(pool, 'owner', { dataRoot: data, home, available: false });
    await assert.rejects(off.prepare('LOCAL_FILES_LIST', { path: shared }), /desktop app/);
    await assert.rejects(off.execute('LOCAL_FILES_READ', { path: note }), /desktop app/);
  } finally {
    await rm(base, { recursive: true, force: true });
  }
});

package main

import (
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"syscall"
)

func main() {
	distribution := os.Getenv("NOD_WSL_DISTRIBUTION")
	if !regexp.MustCompile(`^nod-[a-f0-9]{12}$`).MatchString(distribution) {
		os.Exit(64)
	}
	system := os.Getenv("SYSTEMROOT")
	if !filepath.IsAbs(system) {
		os.Exit(64)
	}
	args := append([]string{"--distribution", distribution, "--user", "root", "--exec", "/usr/local/bin/nod-docker"}, os.Args[1:]...)
	command := exec.Command(filepath.Join(system, "System32", "wsl.exe"), args...)
	for _, key := range []string{"SYSTEMROOT", "USERPROFILE", "LOCALAPPDATA", "TEMP", "TMP"} {
		if value := os.Getenv(key); value != "" {
			command.Env = append(command.Env, key+"="+value)
		}
	}
	if value := os.Getenv("POSTGRES_PASSWORD"); value != "" {
		command.Env = append(command.Env, "POSTGRES_PASSWORD="+value, "WSLENV=POSTGRES_PASSWORD")
	}
	command.SysProcAttr = &syscall.SysProcAttr{HideWindow: true}
	command.Stdin, command.Stdout, command.Stderr = os.Stdin, os.Stdout, os.Stderr
	if error := command.Run(); error != nil {
		if exit, ok := error.(*exec.ExitError); ok {
			os.Exit(exit.ExitCode())
		}
		os.Exit(127)
	}
}

import { execFile } from 'node:child_process';
import { existsSync } from 'node:fs';
import { mkdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { promisify } from 'node:util';
import { cardPage, type Card } from './chart.ts';

const run = promisify(execFile);

function findChrome() {
  const candidates = [
    process.env.CHROME_PATH,
    '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    '/Applications/Chromium.app/Contents/MacOS/Chromium',
    '/Applications/Brave Browser.app/Contents/MacOS/Brave Browser',
    '/usr/bin/google-chrome',
    '/usr/bin/chromium',
    '/usr/bin/chromium-browser',
  ];
  return candidates.find((path): path is string => Boolean(path) && existsSync(path!));
}

export async function renderImages(cards: Card[], directory: string) {
  const chrome = findChrome();
  if (!chrome) throw new Error('No Chrome or Chromium found. Set CHROME_PATH to render images.');
  await mkdir(directory, { recursive: true });
  const files: string[] = [];
  const base = [
    '--headless=new',
    '--disable-gpu',
    '--hide-scrollbars',
    '--virtual-time-budget=3000',
  ];
  for (const card of cards) {
    const page = join(directory, `${card.id}.html`);
    const image = join(directory, `${card.id}.png`);
    await writeFile(page, cardPage(card));
    const url = pathToFileURL(page).href;
    const dom = await run(chrome, [...base, '--window-size=1600,900', '--dump-dom', url], {
      timeout: 60_000,
      maxBuffer: 64 * 1024 * 1024,
    });
    const height = Math.max(900, Number(/<title>(\d+)<\/title>/.exec(dom.stdout)?.[1]) || 900);
    await run(
      chrome,
      [
        ...base,
        '--force-device-scale-factor=2',
        `--window-size=1600,${height}`,
        `--screenshot=${image}`,
        url,
      ],
      { timeout: 60_000 },
    );
    files.push(image);
  }
  return files;
}

import { randomUUID } from 'node:crypto';
import { ObjectStoreConflict, type PrivateObjectStore } from '../../src/ports/object-storage.ts';

export function memoryObjectStore(): PrivateObjectStore {
  const objects = new Map<string, { bytes: Uint8Array; version: string }>();
  return {
    async read(key, maxBytes) {
      const object = objects.get(key);
      if (object && object.bytes.byteLength > maxBytes)
        throw new Error('The private file is too large.');
      return object && { bytes: Uint8Array.from(object.bytes), version: object.version };
    },
    async write(key, bytes, { expectedVersion }) {
      if ((objects.get(key)?.version ?? null) !== expectedVersion) throw new ObjectStoreConflict();
      const version = randomUUID();
      objects.set(key, { bytes: Uint8Array.from(bytes), version });
      return version;
    },
    async remove(key, options = {}) {
      if (
        options.expectedVersion !== undefined &&
        objects.get(key)?.version !== options.expectedVersion
      )
        throw new ObjectStoreConflict();
      objects.delete(key);
    },
  };
}

export function startHeroVideo() {
  const play = document.getElementById('heroPlayBtn');
  const video = document.getElementById('heroVideo');
  if (!play || !video) return;

  play.addEventListener('click', () => {
    play.remove();
    video.closest('.lp-demo-photo')?.classList.add('is-playing');
    video.hidden = false;
    video.focus();
    video.play();
  });
}

import { createHash } from 'node:crypto';
import { readFileSync, readdirSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { Scenario } from '../scenario.ts';

const directory = dirname(fileURLToPath(import.meta.url));
const world = join(directory, '../world');
const ids = readdirSync(directory)
  .filter((name) => name.endsWith('.ts') && name !== 'index.ts')
  .map((name) => name.slice(0, -3))
  .sort();

export const scenarios: Scenario[] = await Promise.all(
  ids.map(async (id) => {
    const definition = (await import(`./${id}.ts`)).default as Scenario;
    if (definition.id !== id) throw new Error(`Scenario ${id}.ts must declare id "${id}".`);
    if (!definition.capabilities.length || definition.seconds <= 0)
      throw new Error(`Scenario ${id} needs capabilities and a time limit.`);
    return definition;
  }),
);

function sources(file: string, found: Set<string>) {
  if (found.has(file)) return found;
  found.add(file);
  for (const [, type, path] of readFileSync(file, 'utf8').matchAll(
    /^(?:import|export)\s+(type\s)?[^;]*?'(\.{1,2}\/[^']+\.ts)'/gm,
  )) {
    if (type) continue;
    const target = resolve(dirname(file), path);
    if (dirname(target) === directory || dirname(target) === world) sources(target, found);
  }
  return found;
}

export function fingerprint(id: string) {
  const hash = createHash('sha256');
  for (const file of [...sources(join(directory, `${id}.ts`), new Set())].sort())
    hash.update(relative(directory, file)).update('\0').update(readFileSync(file, 'utf8'));
  return hash.digest('hex').slice(0, 12);
}
